  return (
    <div role={tipo === 'erro' ? 'alert' : 'status'} className={`rounded-md border px-3 py-2 text-sm ${cores[tipo]}`}>
      {children}
    </div>
  );
}

/** Valor monetÃ¡rio com sinal e cor: positivo em verde, negativo em vermelho (o sinal vai no texto). */
export function Valor({ centavos, texto, className = '', ...props }: { centavos: number; texto: string } & HTMLAttributes<HTMLSpanElement>) {
  const cor = centavos < 0 ? 'text-red-700' : centavos > 0 ? 'text-emerald-800' : 'text-slate-700';
  return (
    <span className={`whitespace-nowrap font-medium tabular-nums ${cor} ${className}`} {...props}>
      {texto}
    </span>
  );
}
import { createContext, useContext, useSyncExternalStore, type ReactNode } from 'react';
import { apagarTudo, carregar, estadoInicial, salvar } from '../storage/storage';
import { falha, ok, type AppState, type Resultado } from '../domain/types';

export type Problema =
  | { tipo: 'corrompido'; bruto: string }
  | { tipo: 'versao-futura'; bruto: string; versao: number };

export interface Snapshot {
  estado: AppState;
  problema: Problema | null;
}

const MSG_GRAVACAO =
  'NÃ£o foi possÃ­vel gravar no navegador (armazenamento cheio ou bloqueado). Nada foi alterado.';

/**
 * Guarda o estado em memÃ³ria e o persiste no storage a cada alteraÃ§Ã£o.
 * Se a gravaÃ§Ã£o falhar, o estado em memÃ³ria nÃ£o muda.
 */
export class Store {
  private snap: Snapshot;
  private ouvintes = new Set<() => void>();

  constructor(private readonly storage: Storage) {
    const carga = carregar(storage);
    this.snap =
      carga.tipo === 'ok'
        ? { estado: carga.estado, problema: null }
        : { estado: estadoInicial(), problema: carga };
  }

  getSnapshot = (): Snapshot => this.snap;

  subscribe = (ouvinte: () => void): (() => void) => {
    this.ouvintes.add(ouvinte);
    return () => {
      this.ouvintes.delete(ouvinte);
    };
  };

  /** Aplica uma operaÃ§Ã£o pura sobre o estado; sÃ³ persiste se ela der certo. */
  aplicar = (operacao: (estado: AppState) => Resultado<AppState>): Resultado<void> => {
    if (this.snap.problema) return falha('Os dados salvos nÃ£o foram carregados; resolva isso antes de continuar.');
    const r = operacao(this.snap.estado);
    if (!r.ok) return r;
    return this.gravar(r.valor);
  };

  /** Troca todo o estado (importaÃ§Ã£o, exemplo, recomeÃ§o), inclusive resolvendo um problema de carga. */
  substituir = (estado: AppState): Resultado<void> => this.gravar(estado);

  iniciarVazio = (): Resultado<void> => this.gravar(estadoInicial());

  /** Remove todas as chaves do app e volta ao primeiro uso. */
  apagarTudo = (): void => {
    apagarTudo(this.storage);
    this.snap = { estado: estadoInicial(), problema: null };
    this.emitir();
  };

  private gravar(estado: AppState): Resultado<void> {
    try {
      salvar(estado, this.storage);
    } catch {
      return falha(MSG_GRAVACAO);
    }
    this.snap = { estado, problema: null };
    this.emitir();
    return ok(undefined);
