@import "tailwindcss";

body {
  @apply bg-slate-50 text-slate-900;
}

/*
 * Tema escuro: redefine as variáveis de cor do Tailwind v4 sob a classe `dark` do <html>,
 * então todo utilitário (bg-white, text-slate-600, ...) muda sem editar componentes.
 * A escala slate é invertida; verde, vermelho, âmbar e azul trocam para tons claros em texto
 * e escuros em fundos. Botões com `text-white` sobre `bg-*-700` ficam escuro sobre tom claro.
 */
html.dark {
  color-scheme: dark;
  --color-white: #111b2e;
  --color-slate-50: #0a1020;
  --color-slate-100: #1e293b;
  --color-slate-200: #334155;
